import * as T from './vendor/three.module.min.js';
// Persistent crossed ribbons. A strike updates vertex buffers; no geometry is reallocated.
export function createLightning({color='#a5dcff',size=1,height=3,wrapped=false}={}){
 const group=new T.Group();group.name='Décharges ramifiées';let cycle=-1;
 const core=new T.MeshBasicMaterial({color:'#f3fbff',transparent:true,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending,toneMapped:false}),glow=new T.MeshBasicMaterial({color,transparent:true,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending,toneMapped:false});
 const buffers=[core,glow].map(material=>{const geometry=new T.BufferGeometry(),array=new Float32Array(64*12*3);geometry.setAttribute('position',new T.BufferAttribute(array,3).setUsage(T.DynamicDrawUsage));let mesh=new T.Mesh(geometry,material);mesh.frustumCulled=false;group.add(mesh);return{geometry,array}});
 function rebuild(seed){let state=(seed+1)*7919;const random=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296};let start=wrapped?new T.Vector3(size*.65,height*.12,-size*.3):new T.Vector3(size*.3,height,0),end=wrapped?new T.Vector3(-size*.45,height*.94,size*.3):new T.Vector3(0,.06,0);
 function path(a,b,displace,passes=4){let points=[a,b];for(let pass=0;pass<passes;pass++){let next=[points[0]];for(let i=1;i<points.length;i++){let m=points[i-1].clone().add(points[i]).multiplyScalar(.5);m.x+=(random()-.5)*displace;m.z+=(random()-.5)*displace;m.y+=(random()-.5)*displace*.4;next.push(m,points[i])}points=next;displace*=.5}return points}
 let points=path(start,end,size*.55),strands=[{points,width:size*.006}];for(let i of [4,8,12]){let p=points[i],b=p.clone().add(new T.Vector3((random()-.5)*size,height*.18*(wrapped?1:-1),(random()-.5)*size));strands.push({points:path(p,b,size*.18,3),width:size*.0035})}
 buffers.forEach(({geometry,array},layer)=>{let offset=0;for(let strand of strands)for(let i=1;i<strand.points.length;i++){let a=strand.points[i-1],b=strand.points[i],direction=b.clone().sub(a).normalize(),side=new T.Vector3().crossVectors(direction,Math.abs(direction.y)<.95?new T.Vector3(0,1,0):new T.Vector3(1,0,0)).normalize(),other=new T.Vector3().crossVectors(direction,side);for(let n of [side,other]){n.multiplyScalar(strand.width*(layer?4:1));let p=[a.clone().sub(n),a.clone().add(n),b.clone().add(n),b.clone().sub(n)];for(let j of [0,1,2,0,2,3]){array[offset++]=p[j].x;array[offset++]=p[j].y;array[offset++]=p[j].z}}}geometry.setDrawRange(0,offset/3);geometry.attributes.position.needsUpdate=true;});
 }
 return{group,update(time,opacity=1){let frame=Math.floor(time/1.2);if(frame!==cycle){cycle=frame;rebuild(frame)}let phase=time%1.2,pulse=phase<.045?1:phase<.09?.12:phase<.15?.85:Math.max(0,1-(phase-.15)/.12)*.35;group.visible=pulse>.01&&opacity>0;core.opacity=pulse*opacity;glow.opacity=pulse*opacity*.22;},dispose(){for(let b of buffers)b.geometry.dispose();core.dispose();glow.dispose()}};
}
